function updateMarketingRoi() {
  const leads = Number($('#mroi-leads')?.value || 120), rate = Number($('#mroi-rate')?.value || 12), close = Number($('#mroi-close')?.value || 30), gross = Number($('#mroi-gross')?.value || 2800);
  const sales = leads * rate / 100 * close / 100, value = sales * gross;
  const values = [['#mroi-leads-out',leads.toLocaleString()],['#mroi-rate-out',rate+'%'],['#mroi-close-out',close+'%'],['#mroi-gross-out','$'+gross.toLocaleString()],['#mroi-sales',sales.toFixed(1)],['#mroi-value','$'+Math.round(value).toLocaleString()]];
  for (const [selector,text] of values) { const el=$(selector); if (el && el.textContent !== text) { el.textContent=text; el.classList.remove('result-pop'); requestAnimationFrame(() => el.classList.add('result-pop')); } }
}
function initReveal() {
  if (matchMedia('(prefers-reduced-motion: reduce)').matches || !('IntersectionObserver' in window)) return;
  document.documentElement.classList.add('reveal-ready');
  const observer = new IntersectionObserver(entries => entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('revealed'); observer.unobserve(entry.target); } }), {threshold:.14});
  document.querySelectorAll('.reveal').forEach(el => observer.observe(el));
}
