async function act(endpoint, body = {}) {
  if (busy) return null;
  busy = true; document.body.classList.add('busy');
  try {
    const res = await fetch(`/api/${endpoint}`, { method:'POST', headers:{ 'Content-Type':'application/json', 'X-Returnlane-Client':'local-demo' }, body:JSON.stringify(body) });
    const data = await res.json(); if (!res.ok) throw new Error(data.error || 'Action failed.');
    state = data.state; render(); return data.result;
  } catch (e) { toast(e.message, true); return null; }
  finally { busy = false; document.body.classList.remove('busy'); }
}
function toast(text, error = false) {
  clearTimeout(toastTimer); $('#toast').textContent = text; $('#toast').className = `visible ${error ? 'error' : ''}`;
  toastTimer = setTimeout(() => $('#toast').className = '', 5500);
}
