function updateRoi() {
  const leads = Number($('#roi-leads')?.value || 0), rate = Number($('#roi-rate')?.value || 0) / 100, close = Number($('#roi-close')?.value || 0) / 100, gross = Number($('#roi-gross')?.value || 0);
  const sales = Math.max(0, leads * rate * close), value = sales * Math.max(0, gross);
  if ($('#roi-sales')) $('#roi-sales').textContent = sales.toFixed(1);
  if ($('#roi-value')) $('#roi-value').textContent = money(Math.round(value * 100));
}
